PUY_rd=read_ebas_merged_STN('C:\github_trend\raw_data\merged_Puy de Dôme.nc', PUY_st);

names_rd=fieldnames(PUY_rd);
% missing data are not removed: data >5e4 should be removed, U data ==999
for i=1: length(names_rd)-3
    PUY_rd.(names_rd{i})(PUY_rd.(names_rd{i})>=999)=NaN;
end
