plotFigControl(PUY_rd,PUY_st.name); %[output:5939af9a] %[output:8fdeb082] %[output:0f9f8765] %[output:27721c16] %[output:5d9d8f75] %[output:3334be82] %[output:73901610] %[output:1abd9a50]

