Ae16.BaW=sum([Ae16.BaW_A2001 Ae16.BaW_A2002 Ae16.BaW_A2003 Ae16.BaW_A2004 Ae16.BaW_A2005 Ae16.BaW_A2006 Ae16.BaW_A2007],2,'omitnan');
